"use client";
import { useState, useEffect } from "react";
import { useRouter, useParams } from "next/navigation";
import { ArrowLeft, Search } from "lucide-react";
import { MENU_CATEGORIES, MENU_ITEMS, getItemsByCategory } from "@/data/menu-data";
import CategoryTabs from '../../../components/CategoryTabs';
import MenuItem from '../../../components/MenuItem';
import OrderSummary from '../../../components/OrderSummary';
import { useOrder } from '../../../context/OrderContext';
import StaffNavbar from '../../../components/StaffNavbar';

export default function OrderPage() {
    const router = useRouter();
    const params = useParams();
    const tableId = parseInt(params.id);

    const {
        tables,
        getOrderByTableId,
        createOrder,
        addItemsToOrder,
    } = useOrder();

    const table = tables.find((t) => t.id === tableId);
    const existingOrder = getOrderByTableId(tableId);

    const [activeCategory, setActiveCategory] = useState("hot-beverages");
    const [selectedItems, setSelectedItems] = useState([]);
    const [searchQuery, setSearchQuery] = useState("");
    const [isLoading, setIsLoading] = useState(false);

    // -----------------------
    // AUTH + LOAD EXISTING ORDER ITEMS
    // -----------------------
    useEffect(() => {
        const token = localStorage.getItem("staffToken");
        if (!token) {
            router.push("/business/staff/login");
            return;
        }

        // If a running order exists, load its items into selection
        if (existingOrder) {
            const mapped = existingOrder.items.map((item) => ({
                id: item.itemId,
                name: item.name,
                price: item.price,
                quantity: item.quantity,
            }));
            setSelectedItems(mapped);
        }
    }, [existingOrder, router]);

    // -----------------------
    // MENU ITEM LOGIC
    // -----------------------
    const handleAddItem = (item) => {
        setSelectedItems((prev) => {
            const existingIdx = prev.findIndex((i) => i.id === item.id);
            if (existingIdx >= 0) {
                const updated = [...prev];
                updated[existingIdx].quantity += 1;
                return updated;
            }
            return [...prev, { ...item, quantity: 1 }];
        });
    };

    const handleQuantityChange = (index, newQty) => {
        if (newQty <= 0) return handleRemoveItem(index);
        setSelectedItems((prev) => {
            const updated = [...prev];
            updated[index].quantity = newQty;
            return updated;
        });
    };

    const handleRemoveItem = (index) => {
        setSelectedItems((prev) => prev.filter((_, i) => i !== index));
    };

    // -----------------------
    // PLACE ORDER (new or update)
    // -----------------------
    const handlePlaceOrder = async () => {
        if (selectedItems.length === 0) return;

        setIsLoading(true);

        try {
            if (existingOrder) {
                // 🔵 ADD ITEMS TO EXISTING ORDER
                await addItemsToOrder(existingOrder.orderId, selectedItems);
            } else {
                // 🟢 CREATE NEW ORDER
                await createOrder(tableId, selectedItems);
            }

            router.push(`/business/staff/table/${tableId}/manage`);
        } catch (err) {
            console.error("Order error:", err);
            alert("Something went wrong!");
        } finally {
            setIsLoading(false);
        }
    };

    // -----------------------
    // FILTER MENU ITEMS
    // -----------------------
    const filteredItems = searchQuery
        ? MENU_ITEMS.filter((item) =>
              item.name.toLowerCase().includes(searchQuery.toLowerCase())
          )
        : getItemsByCategory(activeCategory);

    const getSelectedQuantity = (itemId) => {
        const item = selectedItems.find((i) => i.id === itemId);
        return item ? item.quantity : 0;
    };

    if (!table) return null;

    return (
        <div className="min-h-screen bg-[#FFF8E7] text-gray-800">
            {/* NAVBAR */}
            <StaffNavbar />

            {/* HEADER */}
            <div className="pt-6 pb-2">
                <div className="container mx-auto px-6 flex items-center justify-between">
                    <div className="flex items-center gap-4">
                        <button
                            onClick={() => router.back()}
                            className="p-2 hover:bg-amber-100 rounded-xl text-amber-600"
                        >
                            <ArrowLeft className="w-6 h-6" />
                        </button>
                        <div>
                            <h1 className="text-3xl font-bold bg-gradient-to-r from-amber-500 to-amber-600 bg-clip-text text-transparent">
                                {existingOrder ? "Add More Items" : "Create Order"}
                            </h1>
                            <p className="text-sm text-gray-500">
                                Table {table.tableNumber}
                            </p>
                        </div>
                    </div>

                    <div className="text-right">
                        <p className="text-sm text-gray-500">Items Selected</p>
                        <p className="text-2xl font-bold text-amber-600">
                            {selectedItems.reduce((sum, i) => sum + i.quantity, 0)}
                        </p>
                    </div>
                </div>
            </div>

            {/* MAIN CONTENT */}
            <div className="container mx-auto px-6 py-8">
                <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                    {/* LEFT = MENU */}
                    <div className="lg:col-span-2 space-y-6">
                        {/* SEARCH */}
                        <div className="bg-white p-4 rounded-2xl shadow-lg border border-amber-50">
                            <div className="relative">
                                <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" />
                                <input
                                    type="text"
                                    placeholder="Search menu..."
                                    value={searchQuery}
                                    onChange={(e) => setSearchQuery(e.target.value)}
                                    className="w-full pl-12 pr-4 py-3 border-2 border-gray-100 rounded-xl focus:border-amber-400 outline-none"
                                />
                            </div>
                        </div>

                        {/* CATEGORY TABS */}
                        {!searchQuery && (
                            <CategoryTabs
                                categories={MENU_CATEGORIES}
                                activeCategory={activeCategory}
                                onCategoryChange={setActiveCategory}
                            />
                        )}

                        {/* MENU GRID */}
                        <div className="bg-white rounded-3xl shadow-xl p-6 border border-amber-50">
                            <h2 className="text-2xl font-bold mb-6">
                                {searchQuery
                                    ? `Search Results (${filteredItems.length})`
                                    : MENU_CATEGORIES.find((c) => c.id === activeCategory)?.name}
                            </h2>

                            <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-5">
                                {filteredItems.map((item) => (
                                    <MenuItem
                                        key={item.id}
                                        item={item}
                                        onAdd={handleAddItem}
                                        selectedQuantity={getSelectedQuantity(item.id)}
                                    />
                                ))}
                            </div>
                        </div>
                    </div>

                    {/* RIGHT = ORDER SUMMARY */}
                    <div className="lg:col-span-1">
                        <OrderSummary
                            items={selectedItems}
                            onQuantityChange={handleQuantityChange}
                            onRemoveItem={handleRemoveItem}
                            onPlaceOrder={handlePlaceOrder}
                            isPlacingOrder={isLoading}
                            tableNumber={table.tableNumber}
                            existingOrder={existingOrder}
                        />
                    </div>
                </div>
            </div>
        </div>
    );
}
